def dedup_lines(text):
    seen, kept, removed = set(), [], 0
    for line in text.split('\n'):
        if line == '':
            continue
        line = line.lower()
        if line in seen:
            removed += 1
        else:
            seen.add(line)
            kept.append(line)
    return kept, removed

from collections import Counter


def dedup_lines(text):
    lines = [l for l in text.split('\n') if l != '']
    c = Counter(lines)
    return list(dict.fromkeys(lines)), sum(1 for v in c.values() if v > 1)

